package io.elasticore.sample.mybatis.petstore.application;

import io.elasticore.sample.mybatis.petstore.domain.model.Customer;
import io.elasticore.sample.mybatis.petstore.domain.model.Item;
import io.elasticore.sample.mybatis.petstore.domain.model.OrderLine;
import io.elasticore.sample.mybatis.petstore.domain.model.OrderStatus;
import io.elasticore.sample.mybatis.petstore.domain.model.PurchaseOrder;
import io.elasticore.sample.mybatis.petstore.infrastructure.persistence.PetstoreRepositoryHelper;
import io.elasticore.springboot3.domain.Money;
import io.elasticore.springboot3.validation.NotFoundException;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.time.Clock;
import java.time.LocalDate;

/**
 * Orders. A new one is placed before it is saved: dated, priced from the
 * catalog - whatever price the client sent - with VAT added and a discount
 * taken off, and sent to the customer's home unless it says otherwise.
 *
 * The hexagonal sample states the same in its model (@snapshot, @compute,
 * states:); the layered bundle leaves it to the service, which is this.
 */
@Service
public class PurchaseOrderService extends PurchaseOrderCoreService {

    private final BigDecimal vatRate;
    private final BigDecimal discountRate;
    private final Clock clock;

    public PurchaseOrderService(PetstoreRepositoryHelper helper,
                                @Value("${petstore.vat-rate:5.5}") BigDecimal vatRate,
                                @Value("${petstore.discount-rate:2.25}") BigDecimal discountRate,
                                Clock clock) {
        super(helper);
        this.vatRate = vatRate;
        this.discountRate = discountRate;
        this.clock = clock;
    }

    @Override
    protected void beforeSave(PurchaseOrder order) {
        if (order.getOrderDate() == null) place(order);
    }

    private void place(PurchaseOrder order) {
        order.setOrderDate(LocalDate.now(clock));
        order.setStatus(OrderStatus.PLACED);
        if (order.getDeliveryAddress() == null && order.getCustomerId() != null) {
            order.setDeliveryAddress(helper.getCustomer().findById(order.getCustomerId())
                    .map(Customer::getHomeAddress).orElse(null));
        }
        Money lines = Money.ZERO;
        for (OrderLine line : order.getLines()) {
            Long itemId = line.getItem() == null ? null : line.getItem().getItemId();
            Item item = itemId == null ? null : helper.getItem().findById(itemId).orElse(null);
            if (item == null) {
                throw new NotFoundException("reference.OrderLine.item", "Item {0} does not exist", String.valueOf(itemId));
            }
            line.setItem(item);
            line.setUnitCost(item.getUnitCost());
            line.setSubTotal(item.getUnitCost().times(line.getQuantity()));
            lines = lines.plus(line.getSubTotal());
        }
        Money vat = lines.times(vatRate.movePointLeft(2)).rounded(2);
        Money discount = lines.plus(vat).times(discountRate.movePointLeft(2)).rounded(2);
        order.setTotalWithoutVat(lines);
        order.setVatRate(vatRate);
        order.setVat(vat);
        order.setDiscountRate(discountRate);
        order.setDiscount(discount);
        order.setTotal(lines.plus(vat).minus(discount));
    }
}
